Set Variable [ $r ; Value: Let([
// AddFileMakerErrorToLog(context) custom function
e = Get( LastError );
d = Get( LastErrorDetail );
r = MBS("AddToErrorLog";
JSONSetElement ( "{}" ;
      [ "context" ; context; JSONString ] ;
      [ "lastError" ; e; JSONNumber ] ;
      [ "lastErrorMessage" ; d; JSONString ] ;
      [ "scriptName" ; Get(ScriptName); JSONString ];
      [ "fileName" ; Get(FileName); JSONString ];
      [ "currentTimeStamp" ; Get(CurrentTimestamp); JSONString ]
))
]; e ≠ 0) ]

Set Variable [ $r ; Value: Let([
e = Get(LastError);
r = If( e ≠ 0; AddFileMakerErrorToLog("Found error"); "")
]; e ≠ 0) ]

Set Variable [ $r ; Value: While( 
[ 
	names = ""; 
	// query list of devices
	list = MBS( "ImageCapture.Devices" ); 
	count = ValueCount(list); 
	index = 1
] ; 
	index ≤ count ; 
[ 
	id = GetValue(list; index); 
	// query name for each device
	name = MBS( "ImageCapture.DeviceInfo"; id; "name" ); 
	names = names & id & " -> " & name & ¶; 
	index = index + 1 
] ; 
// return all the names
names ) ]

Set Variable [ $r ; Value: Let ( [
  tokens = MBS("Llama.Tokenize"; $$session; "Hello World.");
  text = MBS("Llama.Detokenize"; $$session; tokens)
]; tokens & ¶ & text ) ]

Set Variable [ $r ; Value: Let ( [
  r1 = MBS("Llama.Tokenize"; $$session; "Hello World."; 0; 0);
  r2 = MBS("Llama.Tokenize"; $$session; "Hello World."; 1; 1)
]; r1 & ¶ & r2 ) ]

Set Variable [ $r ; Value: Let ( [
// new Shell
shell = MBS( "Shell.New" );
// run command with parameters
r = MBS( "Shell.Execute"; shell; "/bin/ls"; "/");
// wait for a result up to 5 seconds
r = MBS( "Shell.Wait"; shell; 5);
// read output
error = MBS( "Shell.ReadErrorText"; shell; "UTF-8");
output = MBS( "Shell.ReadOutputText"; shell; "UTF-8"); 
// free shell
r = MBS("Shell.Release"; shell)
]
; output & error ) ]

Set Variable [ $r ; Value: Let ( [
// new Shell
shell = MBS( "Shell.New" );
// run lsb release to print description for distribution
r = MBS( "Shell.Execute"; shell; "/usr/bin/lsb_release"; "-d");
// wait for a result up to 5 seconds
r = MBS( "Shell.Wait"; shell; 5);
// read result
output = MBS( "Shell.ReadOutputText"; shell; "UTF-8"); 
// free shell
r = MBS("Shell.Release"; shell)
]
; output ) ]

